import{z as n,x as o,o as B,c as C,q as e,j as A,D as a,d as r,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"资本配置","description":"","frontmatter":{"title":"资本配置","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-capital-allocation.md","filePath":"quant/rk-capital-allocation.md","lastUpdated":1791413859000}'),s={name:"quant/rk-capital-allocation.md"};function m(p,E,d,_,h,u){const t=o("Mermaid");return B(),C("div",null,[E[2]||(E[2]=e('<h1 id="资本配置" tabindex="-1">资本配置 <a class="header-anchor" href="#资本配置" aria-label="Permalink to &quot;资本配置&quot;">​</a></h1><div class="epigraph"><p>经济资本回答「要多大的家底才扛得住坏年景」，资本分配回答「这份家底怎么摊到每张桌子并标上价」——前者是计量，后者是治理与激励。</p><footer>—— 据 Tasche, *Capital Allocation to Business Units and Sub-Portfolios*, 2008；Matten, *Managing Bank Capital*, 2000 整理</footer></div><p><a href="/quant/rk-limit-system">上一课</a>把偏好翻译成限额，限额的分母是资本；分母怎么算、怎么摊、怎么定价，是本课的三件事。总量靠经济资本，分摊靠 Euler 分解，定价靠 RAROC 与门槛率的比较——上一课的归因课在此升级为资本课。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三段各有缺口。总量：监管资本是规则口径，与机构真实的联合尾部不同——规则组合给出的是可比较的下限或粗上界，拿它当家底就错配。分摊：各分部独立资本相加大于总资本，分散化收益是真的，但不知道归谁；按独立资本比例分摊，重复收费，惩罚了分散化；平均分摊，补贴了高边际风险的分部——两种懒办法都扭曲激励。定价：业务不上资本价，就会无限扩张表内风险，直到撞上限额——限额是硬墙，价格是斜坡；只有墙没有坡的体系，最后都变成限额边上的寻租。错在哪的根源是一个：资本分配不只是会计问题，它是各分部做决策时面对的相对价格，价格错了，行为就错。</p><p><span class="marginnote">术语翻译：经济资本是「按自己的模型算，坏年景会吃掉多少家底」；监管资本是「规则手册要求你必须备的最低家底」。前者像自家体检报告，后者像全行业统一标准的体检——两份都可能与真实健康有出入，所以平行运转、互相校准，不能互相顶替。</span></p>',6)),(B(),A(i,null,{default:a(()=>[l(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E6%80%BB%E8%B5%84%E6%9C%AC%20100%20%E4%BA%BF%E3%80%81%E5%88%86%E6%95%A3%E5%8C%96%E6%94%B6%E7%9B%8A%2020%20%E4%BA%BF%EF%BC%8C%E6%80%8E%E4%B9%88%E6%91%8A%E7%BB%99%E4%B8%89%E4%B8%AA%E5%88%86%E9%83%A8%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%20A%5B%22%E6%8C%89%E7%8B%AC%E7%AB%8B%E8%B5%84%E6%9C%AC%E6%AF%94%E4%BE%8B%E6%91%8A%EF%BC%9A%E9%87%8D%E5%A4%8D%E6%94%B6%E8%B4%B9%EF%BC%8C%E6%83%A9%E7%BD%9A%E5%88%86%E6%95%A3%E5%8C%96%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E5%B9%B3%E5%9D%87%E5%88%86%E6%91%8A%EF%BC%9A%E8%A1%A5%E8%B4%B4%E9%AB%98%E8%BE%B9%E9%99%85%E9%A3%8E%E9%99%A9%E7%9A%84%E5%88%86%E9%83%A8%22%5D%0A%20%20Q%20--%3E%20C%5B%22Euler%20%E7%BB%84%E6%88%90%E8%B4%A1%E7%8C%AE%EF%BC%9A%E5%90%84%E6%8B%BF%E8%87%AA%E5%B7%B1%E7%9A%84%E5%88%86%E6%95%A3%E5%8C%96%E6%8A%98%E4%BB%B7%22%5D%0A%20%20A%20--%3E%20W%5B%22%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E9%94%99%E4%BA%86%EF%BC%8C%E8%A1%8C%E4%B8%BA%E8%B7%9F%E7%9D%80%E9%94%99%22%5D%0A%20%20B%20--%3E%20W%0A%20%20C%20--%3E%20OK%5B%22%E5%88%86%E9%83%A8%E6%9C%80%E4%BC%98%E4%B8%8E%E6%80%BB%E9%83%A8%E6%9C%80%E4%BC%98%E9%87%8D%E5%90%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>总量：经济资本定义为一年持有期、高置信度下的意外损失，\\(\\mathrm{EC}_\\alpha=\\mathrm{VaR}_\\alpha(L)-\\mathbb{E}[L]\\)，置信度对应目标评级（AA 附近取 \\(99.95\\%\\) 量级）；市场、信用、操作各类分别算出分布，再用相关性矩阵加总并保留分散化收益，压力测试校准尾部——计量单元四课的产出在此汇总。分摊：用<a href="/quant/rk-attribution">风险归因</a>的 Euler 组成贡献，\\(\\mathrm{EC}_i\\) 加总恰等于 \\(\\mathrm{EC}\\)，每个分部自动拿到自己的分散化折价；对冲性业务的贡献可为负，记为负占用。定价：\\(\\mathrm{RAROC}_i=(\\text{收入}_i-\\text{成本}_i-\\text{期望损失}_i)/\\mathrm{EC}_i\\)，与门槛率（股权成本）比较决定扩张或收缩；等价地用 EVA：利润减 \\(\\mathrm{EC}\\) 乘门槛率。</p><p><span class="marginnote">数字实例：某分部年收入 8 亿、成本 3 亿、期望损失 1 亿、占用经济资本 20 亿，则 RAROC=(8−3−1)/20=20%。股东门槛率若为 12%，每 1 元资本多赚 8 分，进扩张名单；门槛率若为 25%，同一笔业务就在收缩名单上——分母 EC 一变，结论立刻反转。</span></p><p><span class="marginnote">负占用不是会计玩笑而是激励设计：一个年省下大量总资本的对冲簿，Euler 贡献为负；若制度只按正数分摊，总部等于在惩罚降低风险的业务。但负占用也要求治理看住「制造对冲再吃补贴」的套利——激励设计的两侧都要堵。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么 Euler 类分摊是激励一致的：Tasche 证明，按组成贡献计费时，各分部在自己的边际收益越过资本成本处扩张，总部利润同时最大化——分部最优与总部最优重合，才谈得上「放权」。分散化收益归分部会引来搭便车的质疑，回应是：收益本来就在总资本的下降里，不分给创造它的人，只会鼓励各分部独立扛风险、组合层重复付资本。RAROC 的坑在门槛率的同质性：用同一个股权成本比所有业务，抹掉了业务间 beta 与相关性的差异，周期性业务被系统性高估；修正要回到组合层的相关性，而不是给每个分部单独讲故事。最后是反身性：配置改变行为，行为改变尾部——去年的相关性与贡献不是明年的，资本模型的校准必须滚动，这与<a href="/quant/regime-break-risk">体制切换失效</a>的教训同源。</p><p><span class="marginnote">常见误区：以为资本配置是年初算一次的算术。配置是反身的：资本价给得宽松，分部就扩张，尾部随之变厚，明年的资本又该重算——去年 99.95% 分位下的贡献不是明年的。静态表只会给过时的价格，校准必须滚动。</span></p>',7)),(B(),A(i,null,{default:a(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MEAS%5B%22%E5%9B%9B%E7%B1%BB%E8%AE%A1%E9%87%8F%EF%BC%9A%E5%88%86%E5%B8%83%E4%B8%8E%E5%B0%BE%E9%83%A8%22%5D%20--%3E%20EC%5B%22%E7%BB%8F%E6%B5%8E%E8%B5%84%E6%9C%AC%EF%BC%9A%E7%BD%AE%E4%BF%A1%E5%BA%A6%E5%88%86%E4%BD%8D%E5%87%8F%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20STRESS%5B%22%E5%8E%8B%E5%8A%9B%E6%B5%8B%E8%AF%95%E6%A0%A1%E5%87%86%22%5D%20--%3E%20EC%0A%20%20EC%20--%3E%20EULER%5B%22Euler%20%E7%BB%84%E6%88%90%E8%B4%A1%E7%8C%AE%EF%BC%9A%E5%8A%A0%E6%80%BB%E7%AD%89%E4%BA%8E%E6%80%BB%E9%87%8F%22%5D%0A%20%20EULER%20--%3E%20RAROC%5B%22RAROC%20%E4%B8%8E%E9%97%A8%E6%A7%9B%E7%8E%87%E6%AF%94%E8%BE%83%22%5D%0A%20%20RAROC%20--%3E%7C%22%E6%89%A9%E5%BC%A0%22%7C%20GROW%5B%22%E5%8A%A0%E9%99%90%E9%A2%9D%E5%8A%A0%E8%B5%84%E6%9C%AC%22%5D%0A%20%20RAROC%20--%3E%7C%22%E6%94%B6%E7%BC%A9%22%7C%20CUT%5B%22%E5%87%8F%E4%BB%93%E6%88%96%E5%AF%B9%E5%86%B2%22%5D%0A%20%20GROW%20--%3E%7C%22%E8%A1%8C%E4%B8%BA%E6%94%B9%E5%8F%98%E5%B0%BE%E9%83%A8%22%7C%20MEAS%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Euler 分解要求对齐次性：ES 满足，VaR 在一般分布上不满足——想用 VaR 资本就接受分解不良或换测度。监管资本与经济资本平行运转：监管附加与缓冲不进 RAROC 分母，否则定价把监管成本藏进总部，激励又错。置信度对应评级是校准约定不是定理，跨周期用同一约定才有可比性。期望损失从损益里扣、意外损失占资本，口径混了会把 RAROC 算成利润率。本课不展开资金转移定价（FTP）的内部利率曲线，那是资产负债管理的事，接口点在「成本」一项的取数口径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经济资本是高置信度的意外损失，四类计量在此汇总；监管资本是平行口径，不可互替。</li><li>分摊用 Euler 组成贡献：加总恰等于总量，分散化折价自动归位，对冲记负占用。</li><li>RAROC 把资本变成相对价格；门槛率要区分业务的 beta，不能一刀切。</li><li>配置是反身的：配置改变行为、行为改变尾部，校准必须滚动。</li><li>出处：Tasche, 2008；Rockafellar and Uryasev, <em>Journal of Risk</em>, 2000；Kalkbrener, <em>Mathematical Finance</em>, 2005；Matten, <em>Managing Bank Capital</em>, 2000；分解基础见本站风险归因课。</li></ul>',4))])}const D=n(s,[["render",m]]);export{R as __pageData,D as default};
